use octo_approval::ApprovalAction;
use serde::{Deserialize, Serialize};
use serde_json::{Value, json};
use sqlparser::{
    ast::{AlterTableOperation, SqliteOnConflict, Statement},
    dialect::SQLiteDialect,
    parser::Parser,
};

use super::{Database, catalog::Store, operations::Operation};
use crate::engine::Analysis;

/// Display facts are captured with the immutable operation, not regenerated by
/// cognition or read from a subsequently changed catalog when a button is used.
#[derive(Clone, Debug, Default, Deserialize, Serialize)]
pub(crate) struct PresentationSnapshot {
    pub resource: String,
    pub action: ApprovalAction,
    pub objects: Vec<String>,
}

impl PresentationSnapshot {
    pub(super) fn capture(store: &Store, request: &Value, analysis: &Analysis) -> Self {
        let namespace = store.namespace();
        Self {
            resource: store.name.clone(),
            action: classify(request),
            objects: analysis
                .objects
                .iter()
                .map(|name| name.strip_prefix(&namespace).unwrap_or(name).to_owned())
                .collect(),
        }
    }
}

fn classify(request: &Value) -> ApprovalAction {
    if request["kind"] == "drop_store" {
        return ApprovalAction::DeleteStore;
    }
    let Some(sql) = request["args"]["sql"].as_str() else {
        return ApprovalAction::ChangeData;
    };
    let Ok(statements) = Parser::parse_sql(&SQLiteDialect {}, sql) else {
        return ApprovalAction::ChangeData;
    };
    match statements.as_slice() {
        [Statement::Delete(_)] => ApprovalAction::DeleteRecords,
        [Statement::Update(_)] => ApprovalAction::UpdateRecords,
        [Statement::Drop { .. }] => ApprovalAction::DropObjects,
        [Statement::AlterTable(table)]
            if table
                .operations
                .iter()
                .any(|op| matches!(op, AlterTableOperation::DropColumn { .. })) =>
        {
            ApprovalAction::DropColumns
        }
        [Statement::Insert(insert)]
            if insert.replace_into
                || insert.or == Some(SqliteOnConflict::Replace)
                || insert.on.is_some() =>
        {
            ApprovalAction::ReplaceRecords
        }
        _ => ApprovalAction::ChangeData,
    }
}

impl Database {
    pub(super) fn operation_details(&self, operation: &Operation) -> Value {
        let response = self.operation_response(operation);
        json!({
            "status": response["status"],
            "operation_id": operation.prepared.id,
            "operation_hash": operation.hash,
            "expires_at": operation.prepared.expires_at,
            "details": operation.prepared.request,
            "effects": operation.prepared.effects,
            "max_affected_rows": operation.scope.max_affected_rows,
            "timeout_ms": operation.scope.timeout_ms,
            "database": self.engine.path().display().to_string(),
            "resource": operation.scope.presentation.resource,
            "objects": operation.scope.presentation.objects,
            "revision": operation.prepared.revision,
        })
    }
}

#[cfg(test)]
mod tests {
    use octo_approval::ApprovalAction;
    use serde_json::json;

    use super::classify;
    use crate::{Database, Limits, database::tests::Fixture};

    #[test]
    fn display_action_uses_parsed_statement_not_words_in_comments_or_literals() {
        assert_eq!(
            classify(&json!({"kind":"drop_store"})),
            ApprovalAction::DeleteStore
        );
        for (sql, expected) in [
            (
                "/* DROP TABLE */ DELETE FROM s_x__meals WHERE note='UPDATE'",
                ApprovalAction::DeleteRecords,
            ),
            (
                "UPDATE s_x__meals SET value=1",
                ApprovalAction::UpdateRecords,
            ),
            ("DROP TABLE s_x__meals", ApprovalAction::DropObjects),
            (
                "ALTER TABLE s_x__meals DROP COLUMN value",
                ApprovalAction::DropColumns,
            ),
            (
                "INSERT OR REPLACE INTO s_x__meals VALUES(1)",
                ApprovalAction::ReplaceRecords,
            ),
            (
                "INSERT INTO s_x__meals VALUES(1)",
                ApprovalAction::ChangeData,
            ),
        ] {
            assert_eq!(
                classify(&json!({"kind":"sql","args":{"sql":sql}})),
                expected
            );
        }
    }

    #[tokio::test]
    async fn authenticated_details_keep_approval_pending_and_snapshot_survives_restart() {
        let f = Fixture::new(Limits::default()).await;
        let store = f.store().await;
        f.table(&store).await;
        let pending = f
            .call(
                "sql.store.drop",
                json!({"store_id":store,"expected_revision":2,"idempotency_key":"drop"}),
            )
            .await
            .unwrap();
        let id = pending["operation_id"].as_str().unwrap();
        let request = json!({"operation_id":id,"include_details":true});
        let details = f
            .call("sql.operation.status", request.clone())
            .await
            .unwrap();
        assert_eq!(details["status"], "approval_required");
        assert_eq!(details["resource"], "test");
        assert_eq!(details["objects"], json!(["data"]));
        assert_eq!(details["operation_hash"], pending["operation_hash"]);
        assert_eq!(details["details"]["kind"], "drop_store");
        assert!(
            f.db.handle(&f.envelope("sql.operation.status", request.clone(), false, "other"))
                .await
                .is_err()
        );
        let reopened = Database::open(
            f.dir.path().join("sql.db"),
            Limits::default(),
            f.authority.clone(),
            vec![],
        )
        .await
        .unwrap();
        assert_eq!(
            reopened
                .handle(&f.envelope("sql.operation.status", request, false, "owner"))
                .await
                .unwrap(),
            details
        );
        let outcome = f
            .call(
                "sql.approval.decide",
                json!({"operation_id":id,"approve":false}),
            )
            .await
            .unwrap();
        assert_eq!(outcome["status"], "rejected");
        assert_eq!(
            f.call("sql.store.describe", json!({"store_id":store}))
                .await
                .unwrap()["objects"]
                .as_array()
                .unwrap()
                .len(),
            1
        );
    }
}
